zonaCargada('f','77_-8',{"h:calatrava-la-nueva":{"epoca":"Castillos y fortalezas","resumen":"En la cima del cerro Alacranejo, a 936 metros de altitud y frente al castillo de Salvatierra, se alza el castillo-convento que fue sede de la Orden de Calatrava.","ver_alli":["El rosetón de la iglesia, visto desde dentro.","Sube a los adarves: enfrente se ve el castillo de Salvatierra.","El camino de acceso al cerro tiene el firme muy irregular: conviene subir despacio."],"fuentes":["https://www.elespanol.com/eldigitalcastillalamancha/vivir/turismo/20260511/castillo-convento-espectacular-espana-joya-siglo-xiii-perfecto-escapada-trt/1003744240719_0.html","https://www.wikidata.org/wiki/Q2933633","https://es.wikipedia.org/wiki/Castillo_de_Calatrava_la_Nueva","https://www.openstreetmap.org/?mlat=38.6659&mlon=-3.8453#map=18/38.6659/-3.8453","https://www.google.com/maps/place/?q=place_id:ChIJzW22aEP5aw0R0mIs5xLnqxw"],"osm":{"w":"http://www.castillodecalatrava.com/p/calatrava-la-nueva.html","wp":"https://es.wikipedia.org/wiki/Castillo_de_Calatrava_la_Nueva","id":5915693656}},"h:corral-de-comedias-de-almagro":{"epoca":"Barroco","resumen":"Es el único corral de comedias del Siglo de Oro que se conserva íntegro. Lo abrió en 1628 el clérigo Leonardo de Oviedo, ampliando el antiguo Mesón del Toro, en la Plaza Mayor de Almagro; la primera función documentada es de 1629.El público se repartía como en el teatro de la época: un patio rodeado por 54 pies derechos de madera sobre basas de piedra, dos pisos de galerías con aposentos, la…","ver_alli":["Fíjate en los pies derechos de madera, los ganchos del toldo y la cazuela frente al escenario.","En el zaguán de entrada, empedrado, está la cruz de Calatrava.","Si coincides con el Festival de Teatro Clásico, ver una función aquí es la mejor visita."],"fuentes":["https://es.wikipedia.org/wiki/Corral_de_comedias_de_Almagro","https://www.openstreetmap.org/?mlat=38.8883&mlon=-3.7119#map=18/38.8883/-3.7119","https://www.google.com/maps/place/?q=place_id:ChIJuRxuaKhfaQ0RjgNNtf-lPpA"],"osm":{"wp":"https://es.wikipedia.org/wiki/Corral_de_comedias_de_Almagro","id":292438632}},"h:palacio-del-viso-del-marques":{"epoca":"Renacimiento","resumen":"Lo mandó levantar Álvaro de Bazán, primer marqués de Santa Cruz y almirante de Felipe II, entre 1564 y la década de 1580, a medio camino entre la corte y los puertos de Cádiz, Cartagena y Lisboa.","ver_alli":["Pasa tiempo mirando los techos: las vistas de puertos y ciudades italianas y las batallas navales.","El patio porticado, con la escalera monumental.","Para entender los frescos ayuda la visita guiada o la audioguía."],"fuentes":["https://www.ancient-history-sites.com/sites/palacio-del-marques-de-santa-cruz/","https://www.inspain.org/es/ciudad-real/visodelmarques/palaciodelmarquesdesantacruz/","https://www.openstreetmap.org/?mlat=38.5232&mlon=-3.5633#map=18/38.5232/-3.5633","https://www.google.com/maps/place/?q=place_id:ChIJeRYBzq-zbg0RU1Wqk9GDGQ0"],"osm":{"wp":"https://es.wikipedia.org/wiki/Viso_del_Marqués","id":527008693}},"n:monumento-natural-volcan-del-cerro-gordo--ciudad-real":{"municipio":"Granátula de Calatrava","resumen":"Monumento natural en Granátula de Calatrava (Ciudad Real). Monumento Natural volcanico visitable en el Campo de Calatrava. Está dentro del Geoparque Mundial UNESCO de Volcanes de Calatrava."},"r:vv-de-poblete--ciudad-real":{"municipio":"Ciudad Real","resumen":"Vía verde lineal de 5,7 km en la provincia de Ciudad Real. Acumula unos 5 m de subida, entre 631 y 651 m de altitud. Se calcula en 1 h 15 min de marcha. Discurre dentro del Geoparque Mundial UNESCO de Volcanes de Calatrava.","web":"https://www.viasverdes.com/itinerarios/itinerario.asp?id=49","distancia_km":5.69,"desnivel_positivo_m":5,"tiempo_estimado_horas":1.25,"altitud_max_m":651,"esf":0,"pu":[[0,"f","",1]],"fo":["l",5.1,"",5.7]},"r:via-verde-del-campo-de-calatrava--ciudad-real":{"municipio":"Calzada de Calatrava","resumen":"Vía verde lineal de 2,8 km en Calzada de Calatrava (Ciudad Real). Acumula unos 15 m de subida, entre 653 y 670 m de altitud. Se calcula en 40 minutos de marcha. Discurre dentro del Geoparque Mundial UNESCO de Volcanes de Calatrava.","web":"https://viasverdes.com/itinerarios/campo-de-calatrava/","distancia_km":2.78,"desnivel_positivo_m":15,"tiempo_estimado_horas":0.6666666666666666,"altitud_max_m":670,"esf":0,"fo":["l",2.3,"",2.8]},"r:pr-cr-46-ruta-de-la-fuente-del-cano--ciudad-real":{"municipio":"Bolaños de Calatrava","resumen":"Sendero de pequeño recorrido (PR) circular de 26 km en Bolaños de Calatrava (Ciudad Real). Sale y vuelve a Bolaños de Calatrava. Acumula 316 m de subida, entre 646 y 855 m de altitud. Se calcula en 6 h 30 min de marcha. Atraviesa en parte el Geoparque Mundial UNESCO de Volcanes de Calatrava.","web":"https://misendafedme.es/buscador-de-senderos/etapa/pr-cr-46-ruta-de-la-fuente-del-cano","distancia_km":26.0,"desnivel_positivo_m":316,"tiempo_estimado_horas":6.5,"altitud_max_m":855,"esf":3,"fo":["c",0.0,"",26.0]},"t:iglesia-de-santa-maria-magdalena-poblete":{"municipio":"Poblete","resumen":"Iglesia parroquial de planta de cruz latina, con muros de tapial y mampostería reforzados con sillares de caliza en las esquinas.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Poblete"],"osm":{"id":234952647}},"t:iglesia-de-nuestra-senora-de-la-consolacion-villar-del-pozo":{"municipio":"Villar del Pozo","resumen":"Parroquia de origen del siglo XIII que daba servicio también a Ballesteros y La Higueruela; el edificio actual es de 1969 tras hundirse la cubierta en 1962.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Villar_del_Pozo"]},"t:iglesia-de-nuestra-senora-de-la-consolacion-ballesteros-de-calatrava":{"municipio":"Ballesteros de Calatrava","resumen":"Iglesia de una sola nave cuyo ábside poligonal es lo único que queda del templo primitivo, probablemente del siglo XIV, ya que el resto se hundió y se rehízo en 1861. Tiene una portada plateresca con medallones de San Pedro y San Pablo y un arco apuntado muy arcaico. En el interior quedan restos de un artesonado que parece mudéjar.","ver_alli":["Portada plateresca con medallones de San Pedro y San Pablo","Ábside poligonal original","Restos del artesonado mudéjar"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ballesteros_de_Calatrava"],"osm":{"id":1340387759}},"t:iglesia-de-santiago-ciudad-real":{"municipio":"Ciudad Real","resumen":"Es la iglesia más antigua de la ciudad, de finales del siglo XIII y comienzos del XIV, a caballo entre el románico tardío y el primer gótico, levantada en lo que fue la judería. Por fuera es un bloque cerrado con canecillos; dentro tiene tres naves con arcos ojivales. Guarda uno de los mejores conjuntos de la ciudad: artesonado mudéjar y pinturas murales góticas.","ver_alli":["Artesonado mudéjar del siglo XIV con lacerías y estrellas","Fresco de ocho dragones en la clave del ábside","Pintura mural gótica de la Misa de San Gregorio y capiteles con demonios y conchas de peregrino"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santiago_(Ciudad_Real)","https://es.wikipedia.org/wiki/Ciudad_Real"],"osm":{"wp":"https://es.wikipedia.org/wiki/Iglesia_de_Santiago_(Ciudad_Real)","bic":1,"id":67499063}},"t:convento-de-las-carmelitas-descalzas-ciudad-real":{"municipio":"Ciudad Real","resumen":"Convento e iglesia del siglo XVII, renacentista y barroco, fundado como monasterio de la Orden de Montesa por el caballero Antonio Galiana y Bermúdez. Desde 1956 lo ocupan las carmelitas descalzas. Es uno de los conventos con la declaración de bien de interés cultural del casco antiguo.","ver_alli":["Fachada de la iglesia","Interior barroco del templo"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real","https://es.wikipedia.org/wiki/Anexo:Bienes_de_inter%C3%A9s_cultural_de_la_provincia_de_Ciudad_Real"],"osm":{"wp":"https://es.wikipedia.org/wiki/Convento_de_las_Carmelitas_Descalzas_(Ciudad_Real)","bic":1,"id":700694904}},"t:convento-de-la-inmaculada-concepcion-franciscanas-ciudad-real":{"municipio":"Ciudad Real","resumen":"Convento de clausura cuya iglesia es lo más notable del conjunto, declarada bien de interés cultural. Por fuera combina tapial de mampostería con verdugadas de ladrillo visto y una espadaña barroca. A los pies se alza un cuerpo de ladrillo con terraza y las típicas celosías de clausura.","ver_alli":["Pórtico a modo de nártex entre contrafuertes","Celosías de clausura en la planta alta","Espadaña barroca de ladrillo"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Convento_de_la_Inmaculada_Concepci%C3%B3n_(Ciudad_Real)"]},"t:portada-del-convento-de-altagracia-ciudad-real":{"municipio":"Ciudad Real","resumen":"Único resto del convento de dominicas de Nuestra Señora de Altagracia, fundado en 1435 y derribado en 1969 por ruina. Su portada se colocó como monumento en una rotonda de la Ronda de Santa María, frente al lugar de la antigua puerta de Santa María de la muralla. Muchas de sus piezas son réplicas de las originales.","ver_alli":["La portada aislada en la rotonda"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Convento_de_las_Dominicas_de_Altagracia_(Ciudad_Real)","https://es.wikipedia.org/wiki/Ciudad_Real"]},"t:torreon-del-alcazar-ciudad-real":{"municipio":"Ciudad Real","resumen":"Pese a su nombre, era la puerta de entrada al alcázar real que mandó levantar Alfonso X el Sabio, donde murió en 1275 su primogénito, el infante Fernando de la Cerda. Está muy restaurado y en buena parte reconstruido, pero es el único resto visible del alcázar. Está en el paseo de Pablo Picasso.","ver_alli":["La puerta-torreón medieval","Restos de muro con foso del alcázar"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real","https://es.wikipedia.org/wiki/Anexo:Bienes_de_inter%C3%A9s_cultural_de_la_provincia_de_Ciudad_Real"],"osm":{"id":263361769}},"t:casa-del-arco-ciudad-real":{"municipio":"Ciudad Real","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Ciudad Real; el punto no marca el sitio exacto.","lat_pueblo":38.9833,"lon_pueblo":-3.9167,"resumen":"Primera casa consistorial de Ciudad Real: edificio de planta del siglo XV con fachada del XVIII, expropiado por los Reyes Católicos al rabino Alvar Díaz para alojar el Ayuntamiento, que estuvo allí hasta 1866. Es el edificio de gobierno más antiguo de la ciudad y de los más antiguos de la provincia.","ver_alli":["Fachada dieciochesca con su arco"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real"]},"t:antiguo-hospital-de-la-misericordia-rectorado-ciudad-real":{"municipio":"Ciudad Real","resumen":"Edificio del siglo XVIII mandado construir por el cardenal Lorenzana como casa de acogida y escuela de oficios para mujeres y desfavorecidos. Con la invasión francesa pasó a ser cuartel de artillería hasta los años noventa, cuando se cedió a la Universidad de Castilla-La Mancha. Se organiza en dos grandes patios con una capilla central.","ver_alli":["Dos patios del siglo XVIII","Puerta del siglo XIV procedente de la antigua judería, en uno de los patios"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real"]},"t:palacio-de-medrano-ciudad-real":{"municipio":"Ciudad Real","resumen":"Casa noble de la calle Paloma con portada del siglo XVI y el escudo de los Treviño. Conserva un elegante patio de columnas. Hoy alberga una delegación de la Junta de Comunidades.","ver_alli":["Portada con el escudo de los Treviño","Patio columnado"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_Medrano","https://es.wikipedia.org/wiki/Ciudad_Real"],"osm":{"id":556049803}},"t:palacio-de-la-diputacion-provincial-ciudad-real":{"municipio":"Ciudad Real","resumen":"Sede de la Diputación, declarada bien de interés cultural, con tres fachadas distintas. La principal está rematada con el escudo de la ciudad y la que da a la plaza de la Merced tiene una tribuna de columnas jónicas.","ver_alli":["Fachada principal con el escudo de la ciudad","Tribuna de columnas jónicas en la fachada de la Merced"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_la_Diputaci%C3%B3n_Provincial_de_Ciudad_Real","https://es.wikipedia.org/wiki/Ciudad_Real"]},"t:museo-lopez-villasenor-casa-de-hernan-perez-del-pulgar-ciudad-real":{"municipio":"Ciudad Real","resumen":"Museo municipal abierto en 1990 en la casa-palacio del capitán Hernán Pérez del Pulgar, edificio del siglo XIV con añadidos del XVI. Reúne la mayor colección de obra del pintor ciudadrealeño Manuel López-Villaseñor. Alberga también el Archivo Histórico Municipal, con la carta fundacional de la ciudad.","ver_alli":["Obra de López-Villaseñor en doce salas","La casa-palacio y su patio"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Museo_L%C3%B3pez_Villase%C3%B1or","https://es.wikipedia.org/wiki/Ciudad_Real"]},"t:museo-del-quijote-ciudad-real":{"municipio":"Ciudad Real","resumen":"Museo dedicado a don Quijote que mezcla obras de arte inspiradas en la novela con montajes audiovisuales. Recrea una imprenta del siglo XVI y a los personajes del libro. Tiene además un centro de estudios y una biblioteca cervantina importante.","ver_alli":["Recreación de una imprenta de época","Biblioteca cervantina"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real"],"osm":{"w":"https://www.ciudadreal.es/servicios-municipales/cultura/museos/museo-del-quijote.html","id":579965552}},"t:museo-diocesano-palacio-episcopal-ciudad-real":{"municipio":"Ciudad Real","resumen":"En el palacio episcopal del siglo XIX se guarda el patrimonio religioso que sobrevivió a la Guerra Civil: piezas románicas, góticas y sobre todo barrocas. Destacan los cantorales del monasterio de Uclés de la Orden de Santiago. Durante la guerra el edificio fue sede del PCE local.","ver_alli":["Cantorales de Uclés","Paso de «La Santa Cena» de Faustino Sanz Herranz"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real"],"osm":{"id":6580174461}},"t:museo-archivo-municipal-elisa-cendrero-ciudad-real":{"municipio":"Ciudad Real","resumen":"Casa de Elisa Cendrero y de Arias, fechada en 1917, que conserva la decoración de su época y evoca el ambiente burgués de finales del siglo XIX. Tras su restauración abrió en 2019 como museo municipal.","ver_alli":["Interiores burgueses de principios del siglo XX"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Ciudad_Real"],"osm":{"id":6580176682}},"t:casa-del-conde-de-la-canada-ciudad-real":{"municipio":"Ciudad Real","resumen":"Edificio de la calle Lanza que une los restos de un palacio renacentista de sillería con una ampliación de ladrillo rojo de comienzos del siglo XX. La parte antigua tiene una portada con triglifos, metopas y bolas, escudos y una buena reja. Encima se añadió un mirador de madera y cristal poco habitual en la ciudad.","ver_alli":["Portada renacentista con escudo","Mirador acristalado de madera","Azulejos de la fachada moderna"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Casa_del_Conde_de_la_Ca%C3%B1ada"],"osm":{"id":561060435}},"t:antiguo-banco-de-espana-ciudad-real":{"municipio":"Ciudad Real","resumen":"Edificio ecléctico proyectado en 1903 por Sebastián Rebollar en la plaza del Pilar. Combina ladrillo y piedra con un orden gigante de pilastras y remata en balaustrada. Dentro tiene un patio central de doble altura con luz cenital.","ver_alli":["Fachada de ladrillo y piedra con pilastras","Balaustrada de remate"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Edificio_del_Banco_de_Espa%C3%B1a_(Ciudad_Real)"]},"t:iglesia-de-san-antonio-de-padua-villanueva-de-san-carlos":{"municipio":"Villanueva de San Carlos","resumen":"Iglesia parroquial del pueblo, en la plaza de San Antonio de Padua.","visita":"horario de culto","fuentes":["https://nominatim.openstreetmap.org/ui/search.html?q=Iglesia+de+San+Antonio+de+Padua+Villanueva+de+San+Carlos"],"osm":{"id":221731893}},"t:ermita-del-santisimo-cristo-de-la-misericordia-la-torre-gorda-miguelturra":{"municipio":"Miguelturra","resumen":"Templo neoclásico de planta circular, empezado a finales del siglo XVIII y terminado en 1815, que los vecinos llaman «la torre gorda». Se levantó tras el supuesto milagro de un cuadro del Crucificado que sudó sangre. Está declarado bien de interés cultural y su gran cúpula sobresale sobre el caserío.","ver_alli":["Planta circular con cuatro capillas orientadas a los puntos cardinales","Cúpula con cimborrio, linterna y veleta","Retablo mayor con el Cristo, patrón del pueblo"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ermita_del_Sant%C3%ADsimo_Cristo_(Miguelturra)","https://es.wikipedia.org/wiki/Miguelturra"],"osm":{"id":168419362}},"t:iglesia-de-nuestra-senora-de-la-asuncion-miguelturra":{"municipio":"Miguelturra","resumen":"Iglesia de los siglos XV y XVI de la que se conserva el ábside, gótico de transición al renacimiento; en el XVIII se añadieron bóveda barroca, capillas y campanario. Guarda un retablo mayor de mediados del siglo XVI, considerado el más antiguo de la provincia.","ver_alli":["Retablo mayor del siglo XVI","Ábside gótico-renacentista","Campanario con chapitel de pizarra"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Miguelturra"],"osm":{"id":16362197}},"t:ermita-convento-de-nuestra-senora-de-la-estrella-miguelturra":{"municipio":"Miguelturra","resumen":"Convento de monjas mercedarias fundado a finales del siglo XVII junto a la antigua ermita de Santa Marina, donde según la tradición unos pastores hallaron la imagen de la Virgen guiados por una estrella. La iglesia, renacentista-barroca, tiene cúpula con los cuatro evangelistas en las pechinas. Junto al templo se puede visitar la cueva del hallazgo.","ver_alli":["Cueva donde según la tradición apareció la Virgen","Cúpula con los evangelistas","Impactos de bala de la Guerra Civil"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Ermita-convento_de_Nuestra_Se%C3%B1ora_de_la_Estrella","https://es.wikipedia.org/wiki/Miguelturra"]},"t:casa-del-inquisidor-miguelturra":{"municipio":"Miguelturra","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Miguelturra; el punto no marca el sitio exacto.","lat_pueblo":38.9647,"lon_pueblo":-3.8911,"resumen":"Antigua casa de la Inquisición en la calle Real, con escudo sobre la puerta; hoy en estado de abandono.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Miguelturra"]},"t:palacio-de-claveria-palacio-del-norte-aldea-del-rey":{"municipio":"Aldea del Rey","resumen":"Casa-palacio renacentista fundada por Felipe II para el clavero de la Orden de Calatrava, el caballero que custodiaba las llaves del castillo-convento de Calatrava la Nueva. En él vivió el cardenal-infante Fernando de Austria. Está en las afueras del pueblo, en proceso de restauración y en la Lista Roja de Hispania Nostra.","ver_alli":["Fachada renacentista","Estructura de casa de encomienda calatrava"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_Claver%C3%ADa","https://es.wikipedia.org/wiki/Aldea_del_Rey"],"osm":{"w":"https://cultura.castillalamancha.es/patrimonio/catalogo-patrimonio-cultural/palacio-de-la-claveria","wp":"https://es.wikipedia.org/wiki/Palacio_de_Clavería","bic":1,"id":499711663}},"t:ermita-de-nuestra-senora-del-valle-aldea-del-rey":{"municipio":"Aldea del Rey","resumen":"Ermita del siglo XIV, de las construcciones más antiguas del pueblo.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Aldea_del_Rey"],"osm":{"id":499714543}},"t:iglesia-de-san-jorge-martir-aldea-del-rey":{"municipio":"Aldea del Rey","resumen":"Iglesia parroquial del siglo XIX.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Aldea_del_Rey"],"osm":{"id":499711662}},"t:iglesia-de-san-juan-bautista-pozuelo-de-calatrava":{"municipio":"Pozuelo de Calatrava","resumen":"Gran iglesia barroca del siglo XVII, bien de interés cultural, que sustituyó a la antigua parroquia destruida por el terremoto de Lisboa de 1755. Es de cruz latina con una llamativa cúpula de media naranja sobre pechinas en el crucero. Por fuera, mampostería de cuarcita con sillería caliza y once contrafuertes.","ver_alli":["Cúpula de media naranja del crucero","Retablo mayor barroco sin policromar","Campanario con chapitel de pizarra"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_San_Juan_Bautista_(Pozuelo_de_Calatrava)","https://es.wikipedia.org/wiki/Pozuelo_de_Calatrava"]},"t:banos-de-fuensanta-pozuelo-de-calatrava":{"municipio":"Pozuelo de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Pozuelo de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.9122,"lon_pueblo":-3.8378,"resumen":"Antiguo balneario de aguas agrias mandado construir por el infante Gabriel de Borbón, hermano de Carlos IV. En el siglo XIX llegó a acoger a unas tres mil personas cada verano, con capilla, casa del médico, guardia civil y salón de baile. Sus aguas se recomendaban para el reuma y los nervios.","ver_alli":["Restos del poblado balneario"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Pozuelo_de_Calatrava"]},"t:castillo-de-salvatierra-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","resumen":"Fortaleza de origen andalusí en Sierra Morena, frente al castillo-convento de Calatrava la Nueva, vigilando uno de los pasos naturales entre la Meseta y el valle del Guadalquivir. Fue frontera disputada en los siglos XI y XII y en 1198 la tomaron los calatravos, que la perdieron en 1211 en un famoso asedio almohade. Hoy son muros descarnados en la Lista Roja de Patrimonio.","ver_alli":["Muros y torres de silueta inconfundible","Vista sobre Calatrava la Nueva al otro lado de la carretera"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Castillo_de_Salvatierra_(Ciudad_Real)","https://es.wikipedia.org/wiki/Calzada_de_Calatrava"],"osm":{"id":959284110}},"t:iglesia-de-nuestra-senora-de-la-asuncion-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","resumen":"Nació a principios del siglo XVII como ermita de Nuestra Señora de los Remedios y se convirtió en parroquia cuando la vieja iglesia ardió en la segunda guerra carlista; fue ampliada en 1926. Su joya son siete tablas de un retablo del siglo XVI pintadas por el toledano Juan Correa de Vivar con escenas de la vida de Cristo. La capilla del Sagrario conserva un retablo de uno de los oratorios del castillo de Calatrava la Nueva.","ver_alli":["Siete tablas de Juan Correa de Vivar en el presbiterio","Retablo procedente de Calatrava la Nueva en la capilla del Sagrario","Camarín de la Virgen de los Remedios"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"],"osm":{"id":4408265592}},"t:ermita-del-salvador-del-mundo-del-calvario-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","resumen":"Ermita extramuros documentada ya en 1463, incendiada en 1657 y reconstruida desde 1780. Es de cruz latina con cúpula y fachada con portada renacentista y amplia espadaña. En las pechinas aparecen los símbolos de las cuatro órdenes militares españolas.","ver_alli":["Tabla de la Oración en el huerto de Juan Correa de Vivar (1550-1557)","Pechinas con las cuatro órdenes militares","Portada de la antigua Casa del Prior con escudo y cruces de Calatrava"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"],"osm":{"id":755670351}},"t:ermita-de-san-sebastian-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","resumen":"Ermita de la primera década del siglo XVI con portada gótica de piedra y ventanas apuntadas; sirvió de enterramiento en la epidemia de 1804.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"],"osm":{"id":1325400758}},"t:silo-pintado-por-okuda-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","resumen":"Uno de los silos de grano más grandes de la provincia, pintado en 2019 por el artista Okuda San Miguel dentro del proyecto «IamTITANES». Su colorido lo ha convertido en un referente del arte urbano en la provincia.","ver_alli":["Mural multicolor de Okuda San Miguel en todo el silo"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:casa-de-la-tercia-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Calzada de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Casa del siglo XVII de piedra con franjas de ladrillo donde se almacenaba la tercia, el impuesto de un tercio del grano. Perteneció a la Mesa Maestral de la Orden de Calatrava. La portada concentra la decoración, con pilastras, escudos y una puerta con flores de lis.","ver_alli":["Portada con tres motivos heráldicos","Puerta con flores de lis"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:casa-del-mayorazgo-de-la-cadena-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Calzada de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Casa del siglo XVII con portada de columnas toscanas y tres escudos de los Nieto, Muñoz y Cisneros.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:hospederia-enfermeria-de-los-caballeros-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Calzada de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Edificio de la Orden de Calatrava para alojar a familiares y visitantes de caballeros y frailes, con patio de columnas y portada con escudo calatravo del XVII.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:espacio-almodovar-centro-cultural-rafael-serrano-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Calzada de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Espacio en el centro cultural del pueblo natal de Pedro Almodóvar con atrezo original de «Volver» y «Los amantes pasajeros».","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:iglesia-de-san-bartolome-valenzuela-de-calatrava":{"municipio":"Valenzuela de Calatrava","resumen":"Iglesia de 1560 levantada sobre el solar de un castillo árabe y con materiales reaprovechados, por lo que en sus muros se ven cruces visigodas. No tiene torre sino espadaña. En una hornacina guarda una virgen gótica, la imagen más antigua del pueblo.","ver_alli":["Cruces visigodas en los muros","Virgen gótica, probablemente Nuestra Señora de la Nava","Retablo con el escudo de los marqueses protectores"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Valenzuela_de_Calatrava"]},"t:ermita-del-santo-cristo-de-la-clemencia-valenzuela-de-calatrava":{"municipio":"Valenzuela de Calatrava","resumen":"Ermita de finales del siglo XVII con cúpula decorada con los escudos de los cuatro evangelistas y campanas de bronce del XIX.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Valenzuela_de_Calatrava"],"osm":{"id":1275370313}},"t:ermita-de-nuestra-senora-de-oreto-y-zuqueca-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","resumen":"Santuario de la patrona, ermita románica del siglo XIII declarada bien de interés cultural, junto al yacimiento de Oreto y Zuqueca. El conjunto reaprovecha arcos, piedras y pilares de época anterior, sobre todo visigoda.","ver_alli":["Elementos visigodos reutilizados","Fábrica románica del siglo XIII"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava","https://es.wikipedia.org/wiki/Anexo:Bienes_de_inter%C3%A9s_cultural_de_la_provincia_de_Ciudad_Real"],"osm":{"id":368269614}},"t:puente-romano-de-baebio-publio-venusto-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","resumen":"Puente romano del siglo I sobre el Jabalón, cerca del santuario de Oreto. Solo se ve cuando baja el nivel del pantano del Jabalón.","ver_alli":["Arcos del puente cuando baja el embalse"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"]},"t:iglesia-de-santa-ana-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","resumen":"Iglesia construida entre los siglos XIV y XVIII en el casco urbano. Guarda la imagen de la Virgen de Oreto y Zuqueca, del siglo XIII. Destacan la torre y el artesonado del coro, del XVI.","ver_alli":["Virgen de Oreto y Zuqueca (s. XIII)","Artesonado del coro del siglo XVI","Torre"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"]},"t:palacio-de-torremejia-de-los-torrubia-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","resumen":"Casa-palacio manchega del siglo XVIII de tres plantas con patio de columnas, declarada bien de interés cultural, en la calle del Arco. Fue de los marqueses de Torremejía, que la donaron a los dominicos; su venta posterior la llevó a un grave deterioro. Anexa está la llamada Casa Mudéjar, del siglo XV.","ver_alli":["Patio de columnas","Casa Mudéjar anexa"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_Torremej%C3%ADa","https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"],"osm":{"id":961055156}},"t:casa-natal-del-general-espartero-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Granátula de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.8,"lon_pueblo":-3.7333,"resumen":"Casa donde nació en 1793 Baldomero Espartero, regente de España; en el pueblo hay también una estatua ecuestre suya.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"]},"t:yacimiento-de-la-encantada-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","resumen":"Poblado fortificado en altura de la Edad del Bronce, con murallas, viviendas y silos. Tiene una cueva asociada a la leyenda de la Encantá, una culebra que se convierte en mujer la noche de San Juan.","ver_alli":["Murallas defensivas","Restos de viviendas y silos","La cueva de la leyenda"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"],"osm":{"w":"https://www.ciudad-real.es/lugares/encantada.php","wp":"https://es.wikipedia.org/wiki/Cerro_de_La_Encantada_(España)","id":961963396}},"t:carapuchetes-granatula-de-calatrava":{"municipio":"Granátula de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Granátula de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.8,"lon_pueblo":-3.7333,"resumen":"Singulares chozos de piedra del campo de Granátula, junto a casas de campo, puentes y norias tradicionales.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Gran%C3%A1tula_de_Calatrava"]},"t:museo-nacional-del-teatro-artes-escenicas-almagro":{"municipio":"Almagro","resumen":"Museo estatal dedicado al teatro con retratos de actores, escultura, figurines, bocetos de escenografía, carteles, fotos, trajes y maquetas. Tiene biblioteca con ediciones y manuscritos de los siglos XVIII a XX y un importante fondo de partituras. Su patio se usa como escenario en el Festival de Teatro Clásico.","ver_alli":["Trajes y maquetas escenográficas","Retratos de actores","Patio del museo"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Museo_Nacional_de_Artes_Esc%C3%A9nicas","https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:museo-etnografico-campo-de-calatrava-almagro":{"municipio":"Almagro","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Almagro; el punto no marca el sitio exacto.","lat_pueblo":38.8882,"lon_pueblo":-3.7118,"resumen":"Museo en una casa restaurada del siglo XVIII cerca de la plaza Mayor, en la calle Chile 6. Reúne en dos plantas y una cueva-bodega herramientas y objetos de oficios rurales hoy transformados o desaparecidos. Las salas recrean los ambientes de trabajo tradicionales.","ver_alli":["Cueva-bodega","Salas de oficios rurales"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:museo-del-encaje-almagro":{"municipio":"Almagro","resumen":"Museo abierto en 2004 en el callejón Villar con picaos, encajes y blondas hechos en Almagro y su comarca.","visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"],"osm":{"h":"Mo off","w":"http://www.almagro.es/turismo/lugar/que-visitar/almagro/museo-del-encaje","id":4409201393}},"t:iglesia-de-la-madre-de-dios-almagro":{"municipio":"Almagro","resumen":"Iglesia gótica tardía con toques renacentistas levantada desde 1546 sobre el antiguo hospital de Nuestra Señora la Mayor. Es de tipo columnario y de salón, con naves de igual altura cubiertas por bóvedas de crucería, muy característico de La Mancha. Es el templo más grande de Almagro y acoge a la Virgen de las Nieves parte del año.","ver_alli":["Naves de igual altura con bóvedas de crucería","Imagen de la Virgen de las Nieves"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"],"osm":{"wp":"https://en.wikipedia.org/wiki/Iglesia_de_la_Madre_de_Dios","id":292444789}},"t:iglesia-de-san-blas-antigua-ermita-del-salvador-almagro":{"municipio":"Almagro","resumen":"Antigua ermita del Salvador que los banqueros alemanes Függer (Fúcares), arrendatarios de los maestrazgos de las órdenes por Carlos V, reedificaron en el siglo XVI en agradecimiento. Se atribuye la segunda fase a Enrique Egas el Mozo. Es de una nave con bóvedas de crucería apoyadas en ménsulas con la heráldica de los Függer.","ver_alli":["Ménsulas con los escudos de los Függer","Inscripción latina de la fundación","Sotocoro con artesonado de rosetas"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:iglesia-de-san-agustin-convento-del-santisimo-sacramento-almagro":{"municipio":"Almagro","resumen":"Iglesia barroca del antiguo convento agustino, terminada en 1719, lo único que quedó tras la desamortización. Es uno de los mejores ejemplos de la visión barroca que une arquitectura y pintura, con notables frescos interiores. Sin culto, hoy funciona como espacio expositivo del Museo Nacional del Teatro.","ver_alli":["Frescos barrocos del interior","Tribunas con celosías sobre las capillas","Columnas de orden gigante de la fachada"],"visita":"horario o cita previa (espacio expositivo)","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:convento-de-la-asuncion-de-calatrava-almagro":{"municipio":"Almagro","resumen":"Monasterio fundado entre 1519 y 1544 por el comendador Gutiérrez de Padilla para monjas calatravas, extramuros de la villa. Es el de arquitectura más ambiciosa de Almagro: iglesia gótica con elementos renacentistas y bóvedas nervadas. Su claustro de dos galerías tiene 60 columnas de mármol de Carrara.","ver_alli":["Claustro renacentista de dos pisos (jónico y toscano)","Bóvedas de crucería de la iglesia","Columnas de mármol del claustro"],"visita":"horario o cita previa (comunidad dominica)","fuentes":["https://es.wikipedia.org/wiki/Convento_de_la_Asunci%C3%B3n_de_Calatrava","https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"],"osm":{"wp":"https://es.wikipedia.org/wiki/Convento_de_la_Asunción_de_Calatrava","bic":1,"id":4409495491}},"t:iglesia-de-san-bartolome-el-real-de-la-compania-almagro":{"municipio":"Almagro","resumen":"Iglesia fundada con licencia de Felipe III en 1602 y construida desde 1625 por los jesuitas, financiada sobre todo por la familia Mera. Las obras se alargaron tanto que en 1767, al expulsarse a los jesuitas, el colegio seguía sin acabar. Esa dilación explica la mezcla de estilos.","ver_alli":["Fachada y cúpula","Mezcla de estilos por su larga construcción"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"],"osm":{"h":"Fr,Sa 18:00-19:30","id":292438589}},"t:antigua-universidad-renacentista-convento-del-rosario-almagro":{"municipio":"Almagro","resumen":"Convento dominico de Nuestra Señora del Rosario fundado en el siglo XVI por el clavero calatravo frey Fernando Fernández de Córdova, que llegó a ser universidad. La iglesia sigue el modelo mendicante de una nave en cruz latina con ábside poligonal. Hoy se usa también como espacio del Festival de Teatro.","ver_alli":["Iglesia de una nave con crucero","Claustro"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Universidad_de_Almagro","https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:ermita-de-san-juan-bautista-almagro":{"municipio":"Almagro","resumen":"Ermita con licencia fundacional de 1626, con nave cubierta por un artesonado mudéjar de par y nudillo decorado con lacerías y escudos. Lo más destacado es la capilla de la Virgen de los Remedios, del siglo XVIII, en cruz griega. Sus pinturas al temple y yeserías recuerdan a las de San Agustín.","ver_alli":["Artesonado mudéjar con escudos","Capilla de los Remedios con pinturas y yeserías"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"],"osm":{"id":292606027}},"t:convento-de-la-encarnacion-dominicas-almagro":{"municipio":"Almagro","resumen":"Iglesia terminada probablemente en 1597, de una nave con capillas laterales y bóveda de cañón con lunetos. En el altar mayor hay una Anunciación de Vicente Carducho. La portada se remató en el siglo XVIII con un escudo sostenido por leones de los condes de Valdeparaíso.","ver_alli":["Anunciación de Vicente Carducho","Capilla de los Orduña","Escudo con leones en la portada"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:palacio-de-los-fucares-almacen-de-los-fugger-almagro":{"municipio":"Almagro","resumen":"Edificio del siglo XVI levantado por los banqueros Függer para administrar y almacenar el mercurio de las minas de Almadén y el grano de las rentas de los maestrazgos. Se organiza en torno a un patio renacentista cuadrado con dos galerías de arcos de ladrillo sobre columnas de caliza.","ver_alli":["Patio renacentista de dos galerías"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:palacio-de-los-condes-de-valdeparaiso-almagro":{"municipio":"Almagro","resumen":"Palacio de Juan de Gaona y Abad, primer conde de Valdeparaíso desde 1705, cuyo hijo fue ministro de Hacienda de Fernando VI. Hoy es propiedad de la Diputación Provincial de Ciudad Real.","ver_alli":["Portada con escudo","Patio"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:teatro-municipal-almagro":{"municipio":"Almagro","resumen":"Coliseo neoclásico construido entre 1861 y 1865 según proyecto de Cirilo Vara, reflejo de los gustos de la burguesía del XIX. Su sala de butacas es elíptica por razones de acústica, con platea, palco y gallinero. La embocadura tiene pilastras de madera y un arco carpanel con pinturas.","ver_alli":["Sala elíptica de tres alturas","Embocadura con arco carpanel pintado"],"visita":"horario de funciones","fuentes":["https://es.wikipedia.org/wiki/Almagro_(Ciudad_Real)"]},"t:castillo-de-dona-berenguela-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","resumen":"Fortaleza árabe de los siglos X y XI de basalto, caliza, yeso y ladrillo, construida para vigilar la vía de Toledo a Córdoba. En 1229 doña Berenguela la donó a la Orden de Calatrava. Recinto almenado con patio de armas, restaurado por la Diputación en 1982; la tradición dice que aquí nació Fernando III el Santo.","ver_alli":["Torre del Homenaje con ventanas geminadas y mazmorra","Restos árabes de baños y aljibes","Foso descubierto en 2003"],"visita":"horario de visita (entrada de pago reducido)","fuentes":["https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava","https://es.wikipedia.org/wiki/Anexo:Bienes_de_inter%C3%A9s_cultural_de_la_provincia_de_Ciudad_Real"]},"t:iglesia-de-san-felipe-y-santiago-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","resumen":"Iglesia del siglo XVI de transición del gótico al renacimiento, de una nave con bóvedas estrelladas. En la Guerra Civil perdió su retablo barroco y su órgano y se usó como cuadra. En la reforma de 2003 aparecieron varios niveles de enterramientos bajo la nave.","ver_alli":["Pila bautismal del siglo XVI con el escudo de la villa","Calvario pintado al fresco del XVII","Rosetón de ladrillo y medallones con la cruz de Calatrava en la portada"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava"],"osm":{"id":545494141}},"t:ermita-de-san-cosme-y-san-damian-del-cristo-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","resumen":"Ermita del siglo XV muy reformada en el XVIII, de cruz latina con cúpula elíptica pintada. Su retablo barroco se salvó en la Guerra Civil gracias a la santera Teresa, que convenció a los asaltantes de que la pared se vendría abajo. En la restauración de 2014 aparecieron pinturas medievales en la nave y trampantojos barrocos.","ver_alli":["Retablo barroco con columnas salomónicas","Frescos góticos de la nave","Espadaña y patio con verja de ladrillo"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava"]},"t:santuario-de-nuestra-senora-de-las-nieves-almagro":{"municipio":"Almagro","resumen":"Conjunto de edificios en torno a la ermita de la Virgen de las Nieves, patrona de Almagro, en un enclave almagreño junto a Bolaños, levantado dentro de un antiguo volcán (el maar de las Nieves). La ermita la reconstruyó entre 1637 y 1641 el hijo de don Álvaro de Bazán, en memoria de la protección de la Virgen a su padre en Lepanto. Está declarado bien de interés cultural e incluye una plaza de toros de forma irregular.","ver_alli":["Camarín de la Virgen con cerámica de Talavera","Escudos de los marqueses de Santa Cruz en las pechinas","Plaza de toros irregular del recinto"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Santuario_de_Nuestra_Se%C3%B1ora_de_las_Nieves_(Bola%C3%B1os_de_Calatrava)","https://es.wikipedia.org/wiki/Anexo:Bienes_de_inter%C3%A9s_cultural_de_la_provincia_de_Ciudad_Real"],"osm":{"id":795356677}},"t:rollo-de-justicia-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Bolaños de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.9056,"lon_pueblo":-3.6664,"resumen":"Rollo de justicia, símbolo de la jurisdicción de la villa.","visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava"]},"t:venta-de-borondo-daimiel":{"municipio":"Daimiel","resumen":"Antigua venta del siglo XVI en el extremo sur del término, junto al viejo Camino Real de Almagro a Manzanares, declarada bien de interés cultural. Es un edificio rectangular de dos plantas con un torreón en una esquina. Es de las pocas ventas camineras antiguas que se conservan en La Mancha.","ver_alli":["Torreón de la esquina suroeste","Estructura de venta caminera"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Venta_de_Borondo","https://es.wikipedia.org/wiki/Daimiel"]},"t:iglesia-de-san-andres-apostol-moral-de-calatrava":{"municipio":"Moral de Calatrava","resumen":"Iglesia que los calatravos levantaron sobre un fuerte anterior y que durante siglos tuvo función de fortaleza con torre vigía. Está dentro del conjunto histórico de Moral, declarado en 1982. En su interior hay un lienzo de Luis Tristán, discípulo de El Greco.","ver_alli":["Lienzo de Luis Tristán","Aspecto fortificado del edificio"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_San_Andr%C3%A9s_Ap%C3%B3stol_(Moral_de_Calatrava)","https://es.wikipedia.org/wiki/Moral_de_Calatrava"]},"t:iglesia-de-nuestra-senora-de-la-asuncion-viso-del-marques":{"municipio":"Viso del Marqués","resumen":"Parroquia de transición gótico-renacentista del siglo XV, con la nave descentrada respecto al presbiterio por levantarse sobre una iglesia anterior. Sobre el coro cuelga «el lagarto del Viso», un cocodrilo disecado del Nilo de unos 5 metros que trajo el marqués de Santa Cruz, Álvaro de Bazán. Guarda una tabla flamenca del Calvario restaurada.","ver_alli":["El cocodrilo disecado sobre el coro","Tabla flamenca del Calvario","Relieves de caza del jabalí"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Se%C3%B1ora_de_la_Asunci%C3%B3n_(Viso_del_Marqu%C3%A9s)","https://es.wikipedia.org/wiki/Viso_del_Marqu%C3%A9s"],"osm":{"id":954412318}},"t:museo-de-ciencias-naturales-avan-viso-del-marques":{"municipio":"Viso del Marqués","resumen":"Museo de la asociación local AVAN con colecciones de fósiles de todas las eras geológicas, desde trilobites a colmillos de elefante, muchos de la propia zona. Suma minerales, zoología y botánica, con una colección de mariposas. Organiza exposiciones micológicas y salidas a la sierra.","ver_alli":["Colección de trilobites","Minerales","Colección de mariposas"],"visita":"horario o cita previa","fuentes":["https://es.wikipedia.org/wiki/Viso_del_Marqu%C3%A9s"],"osm":{"id":6369878625}},"t:ermita-de-la-soledad-miguelturra":{"municipio":"Miguelturra","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Miguelturra; el punto no marca el sitio.","lat_pueblo":38.9647,"lon_pueblo":-3.8911,"resumen":"Ermita sencilla del siglo XVII con contrafuertes cilíndricos, gran espadaña y bóveda con las cruces de las cuatro órdenes militares.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Miguelturra"]},"t:ermita-de-san-anton-miguelturra":{"municipio":"Miguelturra","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Miguelturra; el punto no marca el sitio.","lat_pueblo":38.9647,"lon_pueblo":-3.8911,"resumen":"Ermita popular nacida en el siglo XVI como Hospital de San Sebastián, muy reformada.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Miguelturra"]},"t:ermita-de-san-marcos-peralvillo-miguelturra":{"municipio":"Miguelturra","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Miguelturra; el punto no marca el sitio.","lat_pueblo":38.9647,"lon_pueblo":-3.8911,"resumen":"Ermita rural del siglo XVIII en la pedanía de Peralvillo, con gran espadaña coronada por un nido de cigüeñas.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Miguelturra"]},"t:capilla-del-cristo-de-la-misericordia-pozuelo-de-calatrava":{"municipio":"Pozuelo de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Pozuelo de Calatrava; el punto no marca el sitio.","lat_pueblo":38.9122,"lon_pueblo":-3.8378,"resumen":"Pequeña ermita en el Alto del Polvillo, resto de la antigua parroquia arruinada por el terremoto de 1755, con portada de arco de medio punto y espadaña de ladrillo.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Pozuelo_de_Calatrava"]},"t:santuario-de-nuestra-senora-de-los-santos-pozuelo-de-calatrava":{"municipio":"Pozuelo de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Pozuelo de Calatrava; el punto no marca el sitio.","lat_pueblo":38.9122,"lon_pueblo":-3.8378,"resumen":"Santuario en lo alto de un cerro donde hubo un pequeño fuerte en la Reconquista, construido probablemente a finales del siglo XV o comienzos del XVI. Tiene techumbre de tradición mudéjar con motivos renacentistas y pinturas de 1884 hechas en agradecimiento por librar al pueblo del cólera. Está rodeado de casitas de la hermandad y ofrece buenas vistas del Campo de Calatrava.","ver_alli":["Techumbre mudéjar","Retablo barroco con columnas salomónicas","Las cruces de las cuatro órdenes militares en el arco"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Pozuelo_de_Calatrava"]},"t:castillo-de-los-cristianos-de-don-alonso-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Calzada de Calatrava; el punto no marca el sitio.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Pequeña fortificación de comienzos del siglo XIII en la sierra de la Atalaya, a unos 600 metros del castillo de Salvatierra. Servía de «padrastro», es decir, posición desde la que hostigar o vigilar la fortaleza vecina. Las excavaciones del Ayuntamiento con la Universidad de Castilla-La Mancha han permitido reconstruirlo virtualmente.","ver_alli":["Restos de la estructura en la sierra","Reconstrucción virtual en la oficina de turismo"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:ermita-de-la-soledad-y-patio-de-san-francisco-calzada-de-calatrava":{"municipio":"Calzada de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Calzada de Calatrava; el punto no marca el sitio.","lat_pueblo":38.7039,"lon_pueblo":-3.7764,"resumen":"Ermita del siglo XVII ampliada cuando llegaron los capuchinos, que en 1729 fundaron aquí su convento de San Luis Obispo, vendido en la desamortización de 1843. Del convento queda el patio de San Francisco, centro de la Semana Santa calzadeña, y el salón de la Orden Tercera. El retablo mayor de la ermita es obra de los hermanos Mossi.","ver_alli":["Patio de San Francisco con la hornacina del santo","Retablo de los hermanos Mossi"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Calzada_de_Calatrava"]},"t:santuario-de-nuestra-senora-del-monte-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Bolaños de Calatrava; el punto no marca el sitio.","lat_pueblo":38.9056,"lon_pueblo":-3.6664,"resumen":"Conjunto en la antigua Dehesa de la Moheda con dos ermitas, una primitiva del siglo XIII y otra de finales del XIX y principios del XX. Alberga una de las colecciones de exvotos más numerosas de Castilla-La Mancha. Es además el gran espacio verde del pueblo, con arboledas, fuentes y paseos.","ver_alli":["Colección de exvotos en el coro y la sala-museo","Ermita primitiva del siglo XIII","Arboledas y paseos del recinto"],"visita":"acceso libre al recinto; ermita en horario de culto","fuentes":["https://es.wikipedia.org/wiki/Santuario_de_la_Virgen_del_Monte_(Bola%C3%B1os_de_Calatrava)","https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava"]},"t:pozo-de-la-nieve-viviendas-cueva-bolanos-de-calatrava":{"municipio":"Bolaños de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Bolaños de Calatrava; el punto no marca el sitio.","lat_pueblo":38.9056,"lon_pueblo":-3.6664,"resumen":"Conjunto de viviendas-cueva tradicionales del barrio del Pozo de la Nieve, de propiedad privada.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Bola%C3%B1os_de_Calatrava"]},"t:ermita-de-la-virgen-de-la-sierra-moral-de-calatrava":{"municipio":"Moral de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Moral de Calatrava; el punto no marca el sitio.","lat_pueblo":38.8303,"lon_pueblo":-3.5806,"resumen":"Ermita de la patrona, una talla de estilo románico que procesiona en un paso de madera tallado a mano por dos artesanos del pueblo. En su ermita primitiva aparecieron monedas del rey visigodo Wamba. En 2012 se celebró el VIII centenario de su culto.","ver_alli":["Talla románica de la Virgen","Paso tallado a mano"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Moral_de_Calatrava"]},"t:convento-y-ermita-del-cristo-de-la-humildad-moral-de-calatrava":{"municipio":"Moral de Calatrava","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Moral de Calatrava; el punto no marca el sitio exacto.","lat_pueblo":38.8303,"lon_pueblo":-3.5806,"resumen":"Convento y ermita franciscanos en la plaza de Piedralaves, donde se venera al patrón del pueblo.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Moral_de_Calatrava"]},"t:ermita-de-santiago-o-de-san-blas-moral-de-calatrava":{"municipio":"Moral de Calatrava","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Moral de Calatrava; el punto no marca el sitio.","lat_pueblo":38.8303,"lon_pueblo":-3.5806,"resumen":"Ermita a unos 4 km del pueblo hacia Santa Cruz de Mudela, escenario de la romería de San Blas en febrero.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Moral_de_Calatrava"]}});